// Code Lab · tst-cl-5-2 — LOCAL mutation grader (máy chấm đột biến chạy TRÊN MÁY BẠN).
// Run it inside your labflow-lite project folder:  node cham-tai-may.mjs [test files…]
// (default: the test file(s) of this exercise). Needs the project dependencies (npm ci).
// What it does — same algorithm as the course's mutation labs: your tests must be GREEN on the correct code, then each
// planted bug is written into its file one at a time (the file is ALWAYS restored, even on Ctrl+C) and your tests must
// turn RED; harmless changes must keep them GREEN. It prints N/N when every check passes.
import { readFileSync, writeFileSync } from 'node:fs';
import { spawnSync } from 'node:child_process';

const DE = {
  "id": "tst-cl-5-2",
  "runner": "vitest",
  "config": null,
  "args": null,
  "tests": [
    "demo5/th52.test.js"
  ],
  "dotBien": [
    {
      "file": "src/api/auth.js",
      "from": "{ algorithms: ['HS256'], currentDate: now() }",
      "to": "{ algorithms: ['HS256'] }",
      "label": "expiry checked against the real clock, not the given one"
    },
    {
      "file": "src/api/auth.js",
      "from": ".setExpirationTime(iat + ttlSeconds)",
      "to": ".setExpirationTime(iat + ttlSeconds + 1)",
      "label": "tokens live one second too long"
    },
    {
      "file": "src/api/server.js",
      "from": "if (!mine) return fail(res, 404, 'NOT_FOUND');",
      "to": "if (!booking) return fail(res, 404, 'NOT_FOUND');",
      "label": "anyone can read anyone's booking (IDOR)"
    },
    {
      "file": "src/api/server.js",
      "from": "(req.user.role === role ? next()",
      "to": "(req.user.role !== 'STUDENT' ? next()",
      "label": "lecturers pass the admin check"
    },
    {
      "file": "src/api/server.js",
      "from": "next() : fail(res, 403, 'FORBIDDEN')",
      "to": "next() : fail(res, 401, 'FORBIDDEN')",
      "label": "forbidden answered as 401"
    }
  ],
  "voHai": [
    {
      "file": "src/api/server.js",
      "from": "header.slice(7)",
      "to": "header.slice('Bearer '.length)",
      "label": "refactor: no magic number for the prefix"
    }
  ]
};

const tests = process.argv.slice(2).length ? process.argv.slice(2) : DE.tests;
const npx = (args) => spawnSync('npx', args, { encoding: 'utf8', shell: process.platform === 'win32' });
const run = () => (DE.runner === 'playwright'
  ? npx(['playwright', 'test', ...tests, ...(DE.args ?? ['--project=chromium'])])
  : npx(['vitest', 'run', ...(DE.config ? ['--config', DE.config] : []), ...tests, ...(DE.args ?? [])])).status;

let dangSua = null; // { file, goc } — trả lại nếu bị ngắt giữa chừng
const traLai = () => { if (dangSua) { writeFileSync(dangSua.file, dangSua.goc); dangSua = null; } };
process.on('SIGINT', () => { traLai(); process.exit(130); });

function voi(m, fn) {
  const goc = readFileSync(m.file, 'utf8');
  const n = goc.split(m.from).length - 1;
  if (n !== 1) {
    console.log(`  ? "${m.label}": the text to change was found ${n} times in ${m.file} — your file differs from the course version; copy ${m.file} from this exercise's starter and run again`);
    return null;
  }
  dangSua = { file: m.file, goc };
  writeFileSync(m.file, goc.replace(m.from, () => m.to));
  try { return fn(); } finally { traLai(); }
}

console.log(`${DE.id}: ${tests.join(' ')} (${DE.runner})`);
if (run() !== 0) {
  console.log('✘ Your tests are NOT green on the correct code — fix them first (the code has no bug). 0/' + (DE.dotBien.length + DE.voHai.length));
  process.exit(1);
}
console.log('✔ green on the correct code');
let dat = 0;
for (const m of DE.dotBien) {
  const st = voi(m, run);
  if (st != null && st !== 0) dat++;
  console.log(`${st == null ? '?' : st !== 0 ? '✔ killed   ' : '✘ SURVIVED '} ${m.label}`);
}
for (const m of DE.voHai) {
  const st = voi(m, run);
  if (st === 0) dat++;
  console.log(`${st == null ? '?' : st === 0 ? '✔ still green ' : '✘ RED (brittle)'} harmless: ${m.label}`);
}
const tong = DE.dotBien.length + DE.voHai.length;
console.log(`\n${dat}/${tong} ${dat === tong ? '— all mutants killed. Mark the exercise solved on the website.' : '— not yet.'}`);
process.exitCode = dat === tong ? 0 : 1;

// Sign and verify access tokens (JWT, HS256) with jose. The clock is a parameter, so tests can expire a token.
import { SignJWT, jwtVerify } from 'jose';

export function createAuth({ secret, now = () => new Date() }) {
  const key = new TextEncoder().encode(secret);
  return {
    async sign({ id, role }, ttlSeconds = 3600) {
      const iat = Math.floor(now().getTime() / 1000);
      return new SignJWT({ role })
        .setProtectedHeader({ alg: 'HS256' })
        .setSubject(String(id))
        .setIssuedAt(iat)
        .setExpirationTime(iat + ttlSeconds)
        .sign(key);
    },
    async verify(token) {
      const { payload } = await jwtVerify(token, key, { algorithms: ['HS256'], currentDate: now() });
      return { id: payload.sub, role: payload.role };
    },
  };
}

// My bookings over HTTP (Chapter 11, US-11). Mounted by createApp() in server.js.
//   GET  /api/bookings             → 200, my own bookings (cancelled ones too), by date and start
//   POST /api/bookings/:id/cancel  → 200 the cancelled booking · 404 missing or not mine · 409 already cancelled · 422 too late
import { listMyBookings, cancelMyBooking } from '../booking/myBookings.js';

const CANCEL_STATUS = { NOT_FOUND: 404, ALREADY_CANCELLED: 409, TOO_LATE_TO_CANCEL: 422 };
const MAX_ID = 2147483647;   // PostgreSQL "serial" is a 4-byte int: a bigger id is not a booking, it is a 500 waiting to happen

export function mountMyBookings(app, { repo, requireUser, now, fail, toPublic }) {
  app.get('/api/bookings', requireUser, async (req, res) => {
    res.json((await listMyBookings(repo, req.user.id)).map(toPublic));
  });

  app.post('/api/bookings/:id/cancel', requireUser, async (req, res) => {
    const id = Number(req.params.id);
    if (!Number.isInteger(id) || id < 1 || id > MAX_ID) return fail(res, 404, 'NOT_FOUND');
    const result = await cancelMyBooking(repo, { id, user: req.user, now: now() });
    if (!result.ok) return fail(res, CANCEL_STATUS[result.code], result.code);
    res.json(toPublic(result.booking));
  });
}

// What a client may send. Unknown keys are refused: the role comes from the token, never from the body.
import { z } from 'zod';

const time = z.string().regex(/^([01]\d|2[0-3]):[0-5]\d$/, 'time must be HH:MM between 00:00 and 23:59');

export const BookingInput = z.strictObject({
  lab: z.string().regex(/^[A-Z]{2}-\d{3}$/, 'lab must look like BE-201'),
  date: z.iso.date(),
  start: time,
  end: time,
  seats: z.number().int().min(1).max(200),
});

// LabFlow Lite HTTP API (Chapter 5). Express 5: errors thrown in async handlers reach the error middleware.
import express from 'express';
import { bookLab, BookingError } from '../booking/service.js';
import { BookingInput } from './schemas.js';
import { mountMyBookings } from './myBookings.js';

const RULE_CODES = ['OFF_GRID', 'END_BEFORE_START', 'OUTSIDE_HOURS', 'TOO_LONG'];
const fail = (res, status, code, extra = {}) => res.status(status).json({ error: { code, ...extra } });
const toPublic = (b) => ({ id: b.id, lab: b.lab, date: b.date, start: b.start, end: b.end, seats: b.seats, status: b.status, minutes: b.minutes });

export function createApp({ repo, auth, now = () => new Date() }) {   // now: the clock, for cancelling (Chapter 11)
  const app = express();
  app.use(express.json());

  const requireUser = async (req, res, next) => {
    const header = req.get('authorization') ?? '';
    if (!header.startsWith('Bearer ')) return fail(res, 401, 'UNAUTHENTICATED');
    try {
      req.user = await auth.verify(header.slice(7));
    } catch {
      return fail(res, 401, 'UNAUTHENTICATED');
    }
    next();
  };
  const requireRole = (role) => (req, res, next) => (req.user.role === role ? next() : fail(res, 403, 'FORBIDDEN'));

  app.get('/api/health', (req, res) => res.json({ status: 'ok' }));

  app.post('/api/bookings', requireUser, async (req, res) => {
    const parsed = BookingInput.safeParse(req.body);
    if (!parsed.success) {
      const details = parsed.error.issues.map((i) => ({ path: i.path.join('.'), message: i.message }));
      return fail(res, 400, 'VALIDATION', { details });
    }
    const booking = await bookLab(repo, { ...parsed.data, role: req.user.role, userId: req.user.id });
    res.status(201).location('/api/bookings/' + booking.id).json(toPublic(booking));
  });

  app.get('/api/bookings/:id', requireUser, async (req, res) => {
    const booking = await repo.findById(Number(req.params.id));
    const mine = booking && (booking.userId === req.user.id || req.user.role === 'ADMIN');
    if (!mine) return fail(res, 404, 'NOT_FOUND');   // someone else's booking looks exactly like a missing one
    res.json(toPublic(booking));
  });

  app.get('/api/admin/bookings', requireUser, requireRole('ADMIN'), async (req, res) => {
    res.json((await repo.list()).map(toPublic));
  });

  mountMyBookings(app, { repo, requireUser, now, fail, toPublic });   // Chapter 11: GET /api/bookings, POST /api/bookings/:id/cancel

  app.use((err, req, res, next) => {
    if (err.type === 'entity.parse.failed') return fail(res, 400, 'BAD_JSON');
    if (err instanceof BookingError) {
      if (RULE_CODES.includes(err.code)) return fail(res, 422, err.code);
      if (err.code === 'OVERLAP') return fail(res, 409, 'OVERLAP');
      if (err.code === 'STORAGE_DOWN') return fail(res, 503, 'STORAGE_DOWN');
    }
    return fail(res, 500, 'INTERNAL');
  });
  return app;
}

// My bookings (Chapter 11, US-11): a student lists their own bookings and cancels one.
// The rule (who may cancel, until when) is a pure function in rules/cancel.js; this file only talks to the repository.
import { cancelDecision } from '../rules/cancel.js';

export const listMyBookings = (repo, userId) => repo.listByUser(userId);

// → { ok: true, booking } or { ok: false, code: NOT_FOUND | ALREADY_CANCELLED | TOO_LATE_TO_CANCEL }
export async function cancelMyBooking(repo, { id, user, now }) {
  const decision = cancelDecision(await repo.findById(id), user, now);
  if (!decision.ok) return decision;
  const booking = await repo.cancel(id);   // one atomic step: of two cancels at the same moment, only one wins
  return booking ? { ok: true, booking } : { ok: false, code: 'ALREADY_CANCELLED' };
}

import { checkSlot, needsApproval } from '../rules/booking.js';

export class BookingError extends Error {
  constructor(code, options) {
    super(code, options);
    this.name = 'BookingError';
    this.code = code;
  }
}

// An in-memory "database" whose methods are async, like a real one.
export function createMemoryRepo() {
  const rows = [];
  const latency = () => new Promise((resolve) => setTimeout(resolve, 5));
  return {
    async findOverlap(lab, date, start, end) {
      await latency();
      return rows.find((b) => b.status !== 'CANCELLED' && b.lab === lab && b.date === date && b.start < end && start < b.end) ?? null; // a cancelled booking frees its slot (Chapter 11)
    },
    async insert(booking) {
      await latency();
      const row = { id: rows.length + 1, ...booking };
      rows.push(row);
      return row;
    },
    async findById(id) {
      await latency();
      return rows.find((b) => b.id === id) ?? null;
    },
    async list() {
      await latency();
      return [...rows];
    },
    async remove(id) { // Chapter 10: cancelling deletes the row and returns it (null if there was none)
      await latency();
      const i = rows.findIndex((b) => b.id === id);
      return i === -1 ? null : rows.splice(i, 1)[0];
    },
    count: () => rows.length,
    async listByUser(userId) { // Chapter 11: My bookings — one student's bookings, by date and start
      await latency();
      return rows.filter((b) => b.userId === userId).sort((a, b) => (a.date + a.start).localeCompare(b.date + b.start)).map((b) => ({ ...b }));
    },
    async cancel(id) { // Chapter 11: CONFIRMED or PENDING → CANCELLED in one step; null if missing or already cancelled
      await latency();
      const row = rows.find((b) => b.id === id && b.status !== 'CANCELLED');
      if (!row) return null;
      row.status = 'CANCELLED';
      return { ...row };
    },
  };
}

export async function bookLab(repo, input) {
  const slot = checkSlot(input.start, input.end);
  if (!slot.ok) throw new BookingError(slot.code);
  let clash;
  try {
    clash = await repo.findOverlap(input.lab, input.date, input.start, input.end);
  } catch (err) {
    throw new BookingError('STORAGE_DOWN', { cause: err });
  }
  if (clash) throw new BookingError('OVERLAP');
  const status = needsApproval(input) ? 'PENDING' : 'CONFIRMED';
  try {
    return await repo.insert({ ...input, minutes: slot.minutes, status });
  } catch (err) {
    if (err instanceof BookingError) throw err; // Chapter 4: the database itself can say OVERLAP
    throw new BookingError('STORAGE_DOWN', { cause: err });
  }
}

import { parseTime } from './time.js';

export const OPEN = 7 * 60;          // 07:00
export const CLOSE = 21 * 60;        // 21:00
export const STEP = 30;              // BR-04: 30-minute grid
export const MAX_MINUTES = 240;      // Lite-1: at most 4 hours
export const MAX_DAYS_AHEAD = 14;    // BR-05: at most 14 days ahead
export const APPROVAL_SEATS = 30;    // BR-06: more than 30 seats needs approval

export function checkSlot(start, end) {
  const s = parseTime(start);
  const e = parseTime(end);
  if (s % STEP !== 0 || e % STEP !== 0) return { ok: false, code: 'OFF_GRID' };
  if (e <= s) return { ok: false, code: 'END_BEFORE_START' };
  if (s < OPEN || e > CLOSE) return { ok: false, code: 'OUTSIDE_HOURS' };
  if (e - s > MAX_MINUTES) return { ok: false, code: 'TOO_LONG' };
  return { ok: true, minutes: e - s };
}

export function isWithinBookingWindow(daysAhead) {
  return Number.isInteger(daysAhead) && daysAhead >= 0 && daysAhead <= MAX_DAYS_AHEAD;
}

export function needsApproval({ seats, role }) {
  if (!Number.isInteger(seats) || seats < 1) {
    throw new RangeError('seats must be a positive integer, got ' + seats);
  }
  if (role === 'LECTURER' || role === 'ADMIN') return false;
  return seats > APPROVAL_SEATS;
}

export function createBooking({ lab, seats, role, start, end }) {
  const slot = checkSlot(start, end);
  if (!slot.ok) throw new Error(slot.code);
  return {
    lab,
    start,
    end,
    minutes: slot.minutes,
    status: needsApproval({ seats, role }) ? 'PENDING' : 'CONFIRMED',
  };
}

// Share of opening hours already booked, added booking by booking (0..1).
export function usageRate(bookings) {
  let rate = 0;
  for (const b of bookings) rate += b.minutes / (CLOSE - OPEN);
  return rate;
}

// Lite-3: a booking can be cancelled until 60 minutes before it starts.
export const CANCEL_LIMIT_MINUTES = 60;

export function canCancel(startsAt, now = new Date()) {
  const minutesLeft = (startsAt.getTime() - now.getTime()) / 60000;
  return minutesLeft >= CANCEL_LIMIT_MINUTES;
}

// Chapter 11 (US-11 "My bookings"): when does a booking start, and may this user cancel it now?
// A booking's date and start are Viet Nam wall-clock time (UTC+7), whatever the server's time zone.
export function startsAtVN(date, start) {
  return new Date(date + 'T' + start + ':00+07:00');
}

// booking: { userId, status, date, start } or null · user: { id, role } · now: a Date.
export function cancelDecision(booking, user, now) {
  const isAdmin = user.role === 'ADMIN';
  if (!booking || (booking.userId !== user.id && !isAdmin)) return { ok: false, code: 'NOT_FOUND' };
  if (booking.status === 'CANCELLED') return { ok: false, code: 'ALREADY_CANCELLED' };
  if (!isAdmin && !canCancel(startsAtVN(booking.date, booking.start), now)) return { ok: false, code: 'TOO_LATE_TO_CANCEL' };
  return { ok: true };
}

// Convert between "HH:MM" and minutes since 00:00.
export function parseTime(text) {
  const m = /^([0-9]{2}):([0-9]{2})$/.exec(text);
  if (!m) throw new TypeError('Invalid time "' + text + '", expected HH:MM');
  const h = Number(m[1]);
  const min = Number(m[2]);
  if (h > 23 || min > 59) throw new RangeError('Time out of range: ' + text);
  return h * 60 + min;
}

export function formatTime(minutes) {
  const h = Math.floor(minutes / 60);
  const m = minutes % 60;
  return String(h).padStart(2, '0') + ':' + String(m).padStart(2, '0');
}

// One fresh app per test: its own in-memory repository, its own auth with a test secret, an optional fixed clock.
import { createApp } from '../../src/api/server.js';
import { createAuth } from '../../src/api/auth.js';
import { createMemoryRepo } from '../../src/booking/service.js';

export const SECRET = 'test-secret-not-for-production';

export function makeApi({ now } = {}) {
  const repo = createMemoryRepo();
  const auth = createAuth({ secret: SECRET, now });
  const app = createApp({ repo, auth, now });   // the same clock for tokens and for cancelling (Chapter 11)
  const bearer = async (id, role = 'STUDENT') => 'Bearer ' + (await auth.sign({ id, role }));
  return { app, repo, auth, bearer };
}

export const body = (overrides = {}) => ({ lab: 'BE-201', date: '2026-11-16', start: '08:00', end: '10:00', seats: 20, ...overrides });

